#!/usr/bin/env python3
"""AppFactory bootstrap. Run at repository root; never overwrite differing files."""
from pathlib import Path
import math, struct, zlib, sys
FILES = {'CLAUDE.md': '# AppFactory — repository instructions\nYou are the implementation lead. Work autonomously, but never claim a test or deployment succeeded without evidence. User operates on Android and prefers Danish, one short request, and no extra subscription/API charges.\n\n## Build protocol\n1. Inspect existing files, user goal, constraints and git status. Preserve unrelated changes and existing data. Identify acceptance criteria; ask only if an essential decision cannot be safely made.\n2. Choose the smallest stack that actually meets requirements. Default: static HTML/CSS/ES modules + offline PWA, local storage only for small non-sensitive data; IndexedDB/Dexie for larger structured data and photos. For complex interfaces consider Vite/React and shadcn/ui. Use package versions with a lockfile. Never add a paid API, hosted database, billing or public exposure without permission.\n3. Build complete working flows, not visual mockups. Reuse trusted open-source libraries when worthwhile; check upstream README, license, release, dependencies and compatibility. Do not run third-party install scripts blindly. Use existing installed skills when available; do not claim they are installed otherwise.\n4. Mobile-first: 360–430px widths, no horizontal scrolling, touch targets >=44px, clear labels, loading/error/empty states, keyboard and focus, contrast, responsive layout. Avoid gratuitous effects and generic dashboard clutter.\n5. Security: no secrets in frontend or git, no unsafe HTML injection, no personal data in public hosting, no destructive migration without backup/approval. Do not confuse client storage with authenticated access control. Validate imports. Provide export/import where data matters.\n6. Test: run `npm test`; run actual browser tests (Chromium at 360 and 412px) when available, verify create/edit/delete, reload persistence, offline and export/import as applicable. For new builds run build/lint as applicable. Fix failures before completion. If environment blocks a test, state exactly what was not verified.\n7. Deliver changes on the session branch, concise Danish report with files, test results and any remaining blockers. Never deploy publicly, merge, enable billing or delete an existing project without approval. Do not fabricate links or test results.\n\n## Skills\n- `/build-app` for new apps or major changes\n- `/verify-app` for independent QA\n- `/upgrade-stack` for vetted optional open-source integrations\n- `/publish-app` for release preparation after user approval\n\n## Current starter\nStatic local-first PWA in `public/`; run `npm start` and open http://localhost:4173. `npm test` runs dependency-free Node tests. The demo is replaceable, but keep the requirements and verification discipline. `docs/TOOLS.md` describes optional upstream integrations; these are not preinstalled.\n', '.claude/skills/build-app/SKILL.md': '---\nname: build-app\ndescription: Build a complete mobile-first web app from a user goal, including implementation and verification.\n---\nRead CLAUDE.md. Inspect repository and preserve data. Translate request into 3–8 verifiable acceptance criteria. Choose minimal architecture, implement end-to-end in the current session branch, and use test cases for pure logic and real browser interactions. Use the existing UI tokens or create a coherent design system. Check storage, invalid inputs and error handling. Run /verify-app or its procedure before reporting. Do not stop at a plan or mockup. Do not publish without approval. Report exact evidence in Danish.\n', '.claude/skills/verify-app/SKILL.md': '---\nname: verify-app\ndescription: Independently review and test mobile web apps, persistence, offline behavior, accessibility and release readiness.\n---\nRead CLAUDE.md and acceptance criteria. Inspect diff for regressions, injection, secrets, destructive operations and license risks. Run npm test and build/lint if present. Use Chromium/Playwright when available at 360x800 and 412x915; test navigation, main workflows, reload, error/empty states and no horizontal overflow. Check service worker update and offline if applicable, plus import/export. Inspect console errors. Correct defects and rerun affected tests. Distinguish passed, failed and not run; never invent results.\n', '.claude/skills/upgrade-stack/SKILL.md': '---\nname: upgrade-stack\ndescription: Evaluate and integrate trusted open-source tools or skills without additional paid APIs.\n---\nRead docs/TOOLS.md. Match a tool to a concrete need; do not install overlapping frameworks by default. Inspect upstream source, license, exact install instructions and environment compatibility. Prefer pinned releases and project-local installation; record version and source. Review scripts before execution. Never enable billing, add secrets, or transmit user data to a third party without approval. Verify the skill is discoverable or dependency actually works; report blocked prerequisites instead of claiming success.\n', '.claude/skills/publish-app/SKILL.md': '---\nname: publish-app\ndescription: Prepare a tested app for static hosting and PWA installation, subject to explicit publication approval.\n---\nRun verify-app. Confirm whether app may be public, whether source may be public, hosting limits, data privacy and target. For static projects deploy only public/ or build output. Use relative URLs for project paths. Check HTTPS, service worker, manifest and install icons. Never send private data or secrets to hosting. Provide deployment steps or perform only authorized actions with available tools. Verify actual live URL before reporting success.\n', 'docs/TOOLS.md': '# Optional open-source upgrades\nNot installed by this starter. Use only where useful. Verify current upstream instructions and pin a reviewed release/commit before installing. No paid Claude API is needed to use Claude Code within its Pro limits.\n\n- GStack: https://github.com/garrytan/gstack — broad engineering/QA workflow. Requires environment checks; use instead of, not on top of, other large workflows.\n- GSD: https://github.com/gsd-build/get-shit-done — project planning and execution.\n- Superpowers: https://github.com/obra/superpowers — systematic development and testing.\n- UI/UX Pro Max: https://github.com/nextlevelbuilder/ui-ux-pro-max-skill — design skill; upstream CLI supports Claude. Verify project-local install.\n- Impeccable: https://github.com/pbakaus/impeccable — design critique; upstream plugin or project install. Check Node/engine requirements.\n- Anthropic Skills: https://github.com/anthropics/skills — official examples and skills.\n- Playwright: https://github.com/microsoft/playwright — real browser tests. Install only if browser environment supports it.\n- Vite: https://github.com/vitejs/vite — build tooling for complex apps.\n- shadcn/ui: https://github.com/shadcn-ui/ui — React components.\n- Dexie: https://github.com/dexie/Dexie.js — IndexedDB wrapper.\n- pdf-lib: https://github.com/Hopding/pdf-lib — client-side PDFs.\n- Transformers.js: https://github.com/huggingface/transformers.js — local browser AI; benchmark device and model size.\n\nClaude cloud setup: https://code.claude.com/docs/en/claude-code-on-the-web — network access and setup scripts depend on the environment. If blocked, do not silently switch to paid services.\n', 'README.md': '# AppFactory\nEn genbrugelig, lokal-first startpakke til Claude Code. Ingen API-nøgler, eksterne services eller npm-afhængigheder i standardversionen.\n\n## Fra telefonen\n1. Opret et nyt privat GitHub-repository med README. Upload `appfactory_bootstrap.py` fra startpakken, hvis du ikke allerede har pakket alle filerne ud.\n2. Åbn Claude Code via https://claude.ai/code, forbind GitHub og vælg repository. Bed Claude køre `python3 appfactory_bootstrap.py`, læse `CLAUDE.md`, køre `npm test` og committe/pushe til sessionsbranchen. Hvis filerne allerede er der, spring bootstrap over.\n3. Gennemgå ændringerne og merge, når du er tilfreds. Brug samme instruktioner i nye Claude Code-sessioner. `/build-app` er en lokal skill; en almindelig tekstinstruktion virker også.\n\nEksempel: Byg en komplet mobilapp til registrering af materialer med søgning, foto, offline lagring og JSON-backup. Brug CLAUDE.md, arbejd selvstændigt, test og ret fejl før levering.\n\n## Kør og test\nNode.js 20+; `npm test` (ingen installation). `npm start` starter en lokal statisk server på port 4173. Åbn http://localhost:4173. `public/` er webroden og kan hostes på en statisk HTTPS-host. GitHub Pages kan kræve offentligt repository på Free; publicér kun efter godkendelse. Cloudflare Pages kan tilsluttes manuelt og publicere `public` uden build-kommando, inden for gratisgrænserne.\n\nDemoen er en simpel opgaveliste med tilføjelse, redigering, afslutning, sletning, søgning, JSON-backup og offline-cache. Den kan erstattes af næste app. Data er kun i browseren, ikke krypteret eller synkroniseret; tag backup, og undgå følsomme oplysninger. Ingen tredjeparts-skills er installeret automatisk. Se docs/TOOLS.md.\n', 'package.json': '{"name":"appfactory-starter","version":"1.0.0","private":true,"type":"module","scripts":{"start":"node scripts/serve.mjs","test":"node --test tests/*.test.mjs"},"engines":{"node":">=20"}}\n', '.gitignore': 'node_modules/\n.env\n.env.*\n!.env.example\nplaywright-report/\ntest-results/\n.DS_Store\n.claude/settings.local.json\n', 'scripts/serve.mjs': "import http from 'node:http';\nimport { readFile } from 'node:fs/promises';\nimport { resolve, sep, extname } from 'node:path';\nconst root=resolve('public');\nconst mime={'.html':'text/html; charset=utf-8','.css':'text/css; charset=utf-8','.js':'text/javascript; charset=utf-8','.mjs':'text/javascript; charset=utf-8','.webmanifest':'application/manifest+json','.svg':'image/svg+xml','.png':'image/png'};\nhttp.createServer(async(req,res)=>{try{const url=new URL(req.url,'http://localhost');const path=resolve(root,'.'+decodeURIComponent(url.pathname==='/'?'/index.html':url.pathname));if(!path.startsWith(root+sep)){res.writeHead(403).end();return;}const data=await readFile(path);res.writeHead(200,{'Content-Type':mime[extname(path)]||'application/octet-stream','Cache-Control':'no-cache','X-Content-Type-Options':'nosniff'}).end(data);}catch{res.writeHead(404).end('Not found');}}).listen(Number(process.env.PORT||4173),'127.0.0.1',()=>console.log('http://localhost:'+ (process.env.PORT||4173)));\n", 'public/model.mjs': "export function validate(items){if(!Array.isArray(items)||items.length>10000)throw Error('Ugyldig backup');const ids=new Set();return items.map(x=>{if(!x||typeof x.id!=='string'||!x.id||x.id.length>100||ids.has(x.id)||typeof x.title!=='string'||!x.title.trim()||x.title.length>200||typeof x.done!=='boolean')throw Error('Ugyldig opgave');ids.add(x.id);return {id:x.id,title:x.title.trim(),done:x.done};});}\nexport function upsert(items,id,title){title=title.trim();if(!title||title.length>200)throw Error('Skriv 1–200 tegn');return validate(items.some(x=>x.id===id)?items.map(x=>x.id===id?{...x,title}:x):[...items,{id,title,done:false}]);}\nexport function filter(items,q){return items.filter(x=>x.title.toLocaleLowerCase('da').includes(q.trim().toLocaleLowerCase('da')));}\n", 'public/index.html': '<!doctype html><html lang="da"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#0d2537"><title>AppFactory</title><link rel="manifest" href="manifest.webmanifest"><link rel="icon" href="icon.svg"><link rel="stylesheet" href="style.css"></head><body><main><header><p class="eyebrow">APPFACTORY / STARTER</p><h1>Mit arbejdsbord</h1><p>En lokal, offline-klar app. Dine opgaver gemmes på enheden.</p></header><section aria-label="Opgaver"><div class="stats"><div><span>Åbne</span><strong id="open">0</strong></div><div><span>Afsluttede</span><strong id="done">0</strong></div></div><form id="form"><label for="title">Ny opgave</label><div class="line"><input id="title" required maxlength="200" autocomplete="off" placeholder="Hvad skal du huske?"><button id="submit">Tilføj</button></div><button type="button" id="cancel" class="secondary" hidden>Annuller redigering</button></form><label for="search">Find opgaver</label><input id="search" type="search" placeholder="Søg…"><p id="status" role="status" aria-live="polite"></p><ul id="items"></ul></section><section aria-label="Backup"><h2>Backup</h2><p>Eksportér dine opgaver før du rydder browserdata eller skifter telefon.</p><div class="line"><button id="export" class="secondary">Eksportér JSON</button><button id="import" class="secondary">Importér JSON</button></div><input type="file" id="file" accept=".json,application/json" hidden></section></main><script type="module" src="app.mjs"></script></body></html>\n', 'public/style.css': '*{box-sizing:border-box} [hidden]{display:none!important} :root{font:16px/1.5 system-ui,sans-serif;color:#152b38;background:#edf2f4}body{margin:0}main{max-width:640px;margin:auto;padding:24px 16px 40px}header{background:#0d2537;color:#fff;padding:24px;border-radius:18px;margin-bottom:16px}h1{font-size:clamp(1.7rem,6vw,2.3rem);line-height:1.15;margin:.4rem 0}h2{font-size:1.2rem;margin:0}p{margin:.5rem 0}.eyebrow{font-size:.73rem;letter-spacing:.15em;color:#a7d9d4;font-weight:700}section{background:#fff;padding:18px;border-radius:16px;margin-bottom:14px;border:1px solid #d6e0e5}.stats{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:20px}.stats div{background:#eaf5f3;padding:14px;border-radius:10px}.stats span{display:block;font-size:.85rem}.stats strong{font-size:1.7rem}label{display:block;font-weight:650;margin:12px 0 6px}input,button{font:inherit;min-height:46px;border-radius:9px}input{border:1px solid #849ba7;padding:10px;width:100%;min-width:0;background:white;color:inherit}button{border:1px solid #155e5a;background:#155e5a;color:white;padding:9px 13px;cursor:pointer;font-weight:650}button.secondary{background:white;color:#155e5a}button:focus-visible,input:focus-visible{outline:3px solid #b36a00;outline-offset:2px}.line{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.line input{flex:1;min-width:130px}ul{list-style:none;padding:0;margin:0}li{display:flex;align-items:center;gap:8px;border-top:1px solid #d6e0e5;padding:10px 0;flex-wrap:wrap}li span{flex:1;min-width:90px;overflow-wrap:anywhere}li[data-done=true] span{text-decoration:line-through;color:#526672}li button{font-size:.82rem;padding:8px;min-width:44px}#status{font-size:.88rem;color:#465e6c;overflow-wrap:anywhere}\n', 'public/app.mjs': "import {validate,upsert,filter} from './model.mjs';\nconst $=id=>document.getElementById(id),key='appfactory.tasks.v1';let items=[],editing=null,storageOK=true;\nconst say=s=>{$('status').textContent=s;};\ntry{items=validate(JSON.parse(localStorage.getItem(key)||'[]'));}catch{storageOK=false;say('Lokal lagring kunne ikke læses. Importér en backup eller eksportér de eksisterende data via browserens udviklerværktøjer.');}\nfunction save(next,replace=false){try{if(!storageOK&&!replace)throw Error('Lagring låst efter læsefejl');localStorage.setItem(key,JSON.stringify(next));items=next;storageOK=true;render();return true;}catch(e){say('Kunne ikke gemme: '+e.message);return false;}}\nfunction reset(){editing=null;$('title').value='';$('submit').textContent='Tilføj';$('cancel').hidden=true;}\nfunction button(text,fn){const b=document.createElement('button');b.type='button';b.className='secondary';b.textContent=text;b.addEventListener('click',fn);return b;}\nfunction render(){$('open').textContent=items.filter(x=>!x.done).length;$('done').textContent=items.filter(x=>x.done).length;const list=$('items');list.replaceChildren();const visible=filter(items,$('search').value);if(!visible.length){const li=document.createElement('li');li.textContent='Ingen opgaver fundet.';list.append(li);return;}for(const x of visible){const li=document.createElement('li');li.dataset.done=String(x.done);const span=document.createElement('span');span.textContent=x.title;li.append(span,button(x.done?'Genåbn':'Færdig',()=>{if(save(items.map(y=>y.id===x.id?{...y,done:!y.done}:y)))say('Status opdateret.');}),button('Ret',()=>{editing=x.id;$('title').value=x.title;$('submit').textContent='Gem';$('cancel').hidden=false;$('title').focus();}),button('Slet',()=>{if(confirm('Slet denne opgave?')&&save(items.filter(y=>y.id!==x.id))){if(editing===x.id)reset();say('Opgave slettet.');}}));list.append(li);}}\n$('form').addEventListener('submit',e=>{e.preventDefault();try{if(save(upsert(items,editing||crypto.randomUUID(),$('title').value))){reset();say('Opgave gemt.');}}catch(e){say(e.message);}});$('cancel').onclick=reset;$('search').oninput=render;\n$('export').onclick=()=>{const blob=new Blob([JSON.stringify({version:1,items},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='appfactory-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('import').onclick=()=>$('file').click();$('file').onchange=async()=>{try{const f=$('file').files[0];if(!f)return;if(f.size>5_000_000)throw Error('Filen er for stor');const data=JSON.parse(await f.text());if(data.version!==1)throw Error('Ukendt backupversion');const next=validate(data.items);if(confirm('Erstat alle nuværende opgaver med denne backup?')&&save(next,true)){reset();say('Backup importeret.');}}catch(e){say('Import afvist: '+e.message);}finally{$('file').value='';}};render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>say('Offline-cache kunne ikke aktiveres.'));\n", 'public/sw.js': "const CACHE='appfactory-v1';const ASSETS=['./','./index.html','./style.css','./app.mjs','./model.mjs','./manifest.webmanifest','./icon.svg','./icon-192.png','./icon-512.png'];self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS))));self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('appfactory-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;e.respondWith(fetch(e.request).catch(async()=>{const cached=await caches.match(e.request);if(cached)return cached;if(e.request.mode==='navigate')return (await caches.match('./index.html'))||Response.error();return Response.error();}));});\n", 'public/manifest.webmanifest': '{"id":"./","name":"AppFactory Starter","short_name":"AppFactory","start_url":"./","scope":"./","display":"standalone","background_color":"#edf2f4","theme_color":"#0d2537","icons":[{"src":"icon-192.png","sizes":"192x192","type":"image/png","purpose":"any"},{"src":"icon-512.png","sizes":"512x512","type":"image/png","purpose":"any"}]}\n', 'public/icon.svg': '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><rect width="512" height="512" rx="96" fill="#0d2537"/><path d="M128 352 256 112l128 240H128Z" fill="none" stroke="#a7d9d4" stroke-width="34" stroke-linejoin="round"/><path d="M190 280h132" stroke="#a7d9d4" stroke-width="30" stroke-linecap="round"/></svg>\n', 'tests/model.test.mjs': "import test from 'node:test';import assert from 'node:assert/strict';import {validate,upsert,filter} from '../public/model.mjs';\ntest('create and trim',()=>assert.deepEqual(upsert([],'1','  Pumpe '),[{id:'1',title:'Pumpe',done:false}]));\ntest('edit retains state',()=>assert.deepEqual(upsert([{id:'1',title:'A',done:true}],'1','B'),[{id:'1',title:'B',done:true}]));\ntest('reject blank and long title',()=>{assert.throws(()=>upsert([],'1',' '));assert.throws(()=>upsert([],'1','a'.repeat(201)));});\ntest('reject duplicate IDs and malformed backup',()=>{const x={id:'1',title:'A',done:false};assert.throws(()=>validate([x,x]));assert.throws(()=>validate([{...x,done:'false'}]));assert.throws(()=>validate(null));});\ntest('Danish case-insensitive search',()=>assert.equal(filter([{title:'VÆRELSE'}],'værelse').length,1));\ntest('literal text stays literal',()=>assert.equal(upsert([],'1','<script>')[0].title,'<script>'));\n", '.github/workflows/ci.yml': "name: AppFactory checks\non:\n  push:\n  pull_request:\npermissions:\n  contents: read\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-node@v4\n        with:\n          node-version: '22'\n      - run: npm test\n"}

def png(n):
    def chunk(t,d): return struct.pack('!I',len(d))+t+d+struct.pack('!I',zlib.crc32(t+d)&0xffffffff)
    def distance(x,y,a,b,c,d):
        u,v=c-a,d-b; q=max(0,min(1,((x-a)*u+(y-b)*v)/(u*u+v*v)))
        return math.hypot(x-a-q*u,y-b-q*v)
    raw=bytearray()
    for j in range(n):
        raw.append(0)
        for i in range(n):
            x,y=(i+.5)*512/n,(j+.5)*512/n
            dist=min(distance(x,y,128,352,256,112),distance(x,y,256,112,384,352),distance(x,y,384,352,128,352),distance(x,y,190,280,322,280))
            raw.extend((167,217,212) if dist<17 else (13,37,55))
    return b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR',struct.pack('!2I5B',n,n,8,2,0,0,0))+chunk(b'IDAT',zlib.compress(raw,9))+chunk(b'IEND',b'')

def main():
    all_files={k:v.encode('utf-8') for k,v in FILES.items()}
    for n in (192,512): all_files[f'public/icon-{n}.png']=png(n)
    conflicts=[k for k,v in all_files.items() if Path(k).exists() and Path(k).read_bytes()!=v]
    # GitHub's generated README is safe to keep; preserve rather than overwrite.
    if 'README.md' in conflicts:
        all_files['APPFACTORY-README.md']=all_files.pop('README.md'); conflicts.remove('README.md')
        p=Path('APPFACTORY-README.md')
        if p.exists() and p.read_bytes()!=all_files[str(p)]: conflicts.append(str(p))
    if conflicts:
        print('No files written. Conflicts: '+', '.join(conflicts),file=sys.stderr);return 1
    for k,v in all_files.items():
        p=Path(k);p.parent.mkdir(parents=True,exist_ok=True)
        if not p.exists(): p.write_bytes(v)
    print(f'AppFactory ready: {len(all_files)} files. Run npm test, then npm start.')
    return 0
if __name__=='__main__':sys.exit(main())
